#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // length characterization
        res@.len() == if numbers@.len() == 0 { 0 } else { 2 * numbers@.len() - 1 },
        // even indices are original elements
        forall|k: int|
            0 <= k && k < numbers@.len() ==>
                res@[2 * k] == numbers@[k],
        // odd indices are delimiter (only those that exist)
        forall|k: int|
            0 <= k && k + 1 < numbers@.len() ==>
                res@[2 * k + 1] == delim,
{
    let n: usize = numbers.len();
    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            res@.len() == if i == 0 { 0 } else { 2 * i - 1 },
            // already-placed numbers
            forall|k: int|
                0 <= k && k < i as int ==>
                    res@[2 * k] == numbers@[k],
            // already-placed delimiters (between placed numbers)
            forall|k: int|
                0 <= k && k + 1 < i as int ==>
                    res@[2 * k + 1] == delim,
        decreases (n - i)
    {
        // push the next number
        res.push(numbers[i]);
        // After pushing a number, res length becomes 2*i (or 1 when i=0)
        // We'll restore the target shape by optionally pushing a delimiter.
        if i + 1 < n {
            res.push(delim);
        }
        i += 1;
    }

    res
}

} // verus!